={{ (() => {
  const c = $json;
  const reasons = { complaint: 'Queja', adverse_event: 'Evento adverso', severe_allergy: 'Alergia grave',
    special_request: 'Petición especial', reservation_not_found: 'Reserva no encontrada',
    tool_failure: 'Fallo del sistema', wants_human: 'Quiere hablar con una persona' };
  const head = c.urgency === 'urgent' ? '🔴🔴 RECORDATORIO URGENTE' : '🟡 Recordatorio';
  return [head + ' — Caso #' + c.id + ' sin atender desde hace ' + c.minutes_open + ' min (aviso ' + c.escalation_count + ' de ' + c.max_reminders + ').',
    'Motivo: ' + (reasons[c.reason] || c.reason) + (c.guest_name ? ' · Huésped: ' + c.guest_name : ''),
    'Detalles en el mensaje original.'].join('\n');
})() }}
